import React, { useState, useEffect } from 'react';
import { getNotifications } from '../data/dataFetching';


function NavNotice() {
    const [notifications, setNotifications] = useState([]);

    useEffect(() => {
        getNotifications().then(data => setNotifications(data));
    }, []);

    {/* Function to get the icon class based on the notification type */}
    const getIconClass = (type) => {
        switch (type) {
        case 'warning':
            return 'bi bi-exclamation-circle text-warning';
        case 'error':
            return 'bi bi-x-circle text-danger';
        case 'success':
            return 'bi bi-check-circle text-success';
        case 'info':
            return 'bi bi-info-circle text-primary';
        default:
            return '';
        }
    };


    return (
        <li className='notice-item dropdown'>
            <a className='notice-link notice-icon' data-bs-toggle='dropdown'>
                <i className='bi bi-bell'></i>
            </a>

            <ul className='dropdown-menu dropdown-menu-end dropdown-menu-arrow notifications mt-3'>
                <li className='dropdown-header'>
                    You have {notifications.length} notifications
                </li>

                <li>
                    <hr className='dropdown-divider'/>
                </li>

                {/* Notifications 

                */}

                {notifications.map((notification, index) => (
                    <React.Fragment key={index}>
                        <li className='notification-item'>
                        <i className={getIconClass(notification.type)}></i>
                        <div>
                            <h4>{notification.title}</h4>
                            <p>{notification.message}</p>
                            <p>{notification.time}</p>
                        </div>
                        </li>
                        <li>
                        <hr className='dropdown-divider' />
                        </li>
                    </React.Fragment>
                ))}

                
                <li className='dropdown-footer'>
                    
                    <a href='/notifications'>Show all notifications</a>

                </li>
            </ul>
        </li>
    )
}

export default NavNotice;
